const products=[{id:1,c:'Свет',e:'💡',n:'Настольная лампа',p:4200},{id:2,c:'Свет',e:'◯',n:'Подвесной светильник',p:6900},{id:3,c:'Декор',e:'🏺',n:'Керамическая ваза',p:2800},{id:4,c:'Декор',e:'▧',n:'Настенное панно',p:3500},{id:5,c:'Текстиль',e:'▰',n:'Декоративная подушка',p:1900},{id:6,c:'Текстиль',e:'〰',n:'Плед из хлопка',p:3900}],cart=new Map();const chat=document.querySelector('#chat'),actions=document.querySelector('#actions');const money=n=>new Intl.NumberFormat('ru-RU').format(n)+' ₽',pause=()=>new Promise(r=>setTimeout(r,170));
function msg(t,who='bot',ok=false){const x=document.createElement('div');x.className=`msg ${who}${ok?' success':''}`;x.textContent=t;chat.append(x);chat.scrollTop=chat.scrollHeight}function opts(a,fn){actions.innerHTML='';a.forEach(x=>{const b=document.createElement('button');b.className='choice';b.innerHTML=`${x[0]}<small>${x[1]||''}</small>`;b.onclick=()=>fn(x[2]??x[0]);actions.append(b)})}async function bot(t){await pause();msg(t)}
function render(category='Все'){document.querySelector('#grid').innerHTML=products.filter(p=>category==='Все'||p.c===category).map(p=>`<article class="product" data-id="${p.id}"><i>${p.e}</i><b>${p.n}</b><span>${money(p.p)}</span></article>`).join('');document.querySelectorAll('.product').forEach(x=>x.onclick=()=>showProduct(+x.dataset.id))}function filters(){const cats=['Все','Свет','Декор','Текстиль'];document.querySelector('#filters').innerHTML=cats.map((x,i)=>`<button class="${i?'':'active'}">${x}</button>`).join('');document.querySelectorAll('#filters button').forEach(x=>x.onclick=()=>{document.querySelectorAll('#filters button').forEach(b=>b.classList.remove('active'));x.classList.add('active');render(x.textContent)})}
function totals(){const count=[...cart.values()].reduce((a,b)=>a+b,0),sum=[...cart].reduce((a,[id,q])=>a+products.find(p=>p.id===id).p*q,0);document.querySelector('#cart-badge').textContent=count;document.querySelector('#cart-total').textContent=money(sum);return{count,sum}}
function add(id){cart.set(id,(cart.get(id)||0)+1);totals();const p=products.find(x=>x.id===id);msg(`Добавить: ${p.n}`,'user');bot('Товар добавлен в корзину. Продолжить покупки или открыть корзину?');opts([['Каталог','показать категории'],['Корзина',`${totals().count} товар(а)`]],x=>x==='Корзина'?openCart():home())}
async function showProduct(id){const p=products.find(x=>x.id===id);msg(p.n,'user');actions.innerHTML='';await bot(`${p.e} ${p.n}\nКатегория: ${p.c}\nЦена: ${money(p.p)}\nДемонстрационное описание товара.`);opts([['Добавить в корзину',money(p.p),id],['В избранное','сохранить товар','fav'],['Назад к каталогу','']],x=>x===id?add(id):x==='fav'?favorite(p):home())}
async function favorite(p){msg('В избранное','user');actions.innerHTML='';await bot(`${p.n} сохранён в избранном.`);opts([['Вернуться в каталог']],home)}function home(){msg('Каталог','user');bot('Выберите категорию или товар на витрине.');opts([['Свет'],['Декор'],['Текстиль'],['Корзина',`${totals().count} товар(а)`]],x=>x==='Корзина'?openCart():(render(x),bot(`Категория «${x}» открыта.`)))}
async function openCart(){msg('Корзина','user');actions.innerHTML='';if(!cart.size){await bot('Корзина пока пуста. Выберите товар в каталоге.');opts([['Перейти в каталог']],home);return}const lines=[...cart].map(([id,q])=>{const p=products.find(x=>x.id===id);return`${p.n} × ${q} — ${money(p.p*q)}`});await bot(`В корзине:\n${lines.join('\n')}\nИтого: ${money(totals().sum)}`);opts([['Оформить заказ'],['Очистить корзину'],['Продолжить покупки']],x=>x==='Оформить заказ'?checkout():x==='Очистить корзину'?(cart.clear(),totals(),openCart()):home())}
async function checkout(){msg('Оформить заказ','user');actions.innerHTML='';await bot('Укажите имя и телефон. Менеджер подтвердит наличие и детали получения.');actions.innerHTML=`<form class="form" id="order"><input name="name" aria-label="Имя" placeholder="Имя" required><input name="phone" aria-label="Телефон" type="tel" placeholder="+7 999 000-00-00" required><small id="err"></small><button>Продолжить</button></form>`;document.querySelector('#order').onsubmit=order}
async function order(e){e.preventDefault();const name=e.currentTarget.name.value.trim(),phone=e.currentTarget.phone.value.trim();if(!name||phone.replace(/\D/g,'').length<11){document.querySelector('#err').textContent='Проверьте имя и телефон.';return}msg(`${name}, ${phone}`,'user');actions.innerHTML='';await bot(`Проверьте заказ:\nТоваров: ${totals().count}\nСумма: ${money(totals().sum)}\n${name}, ${phone}`);opts([['Подтвердить заказ','данные верны'],['Вернуться в корзину']],x=>x.startsWith('Подтвердить')?confirm(name,phone):openCart())}
async function confirm(name,phone){msg('Подтвердить заказ','user');actions.innerHTML='';const id='MR-'+String(Date.now()).slice(-6);await bot(`Заказ ${id} принят ✅\nМенеджер получил состав заказа и контакты.`,true);opts([['Новый заказ'],['Показать каталог']],()=>{cart.clear();totals();home()})}
document.querySelector('#cart-open').onclick=openCart;document.querySelector('#all').onclick=()=>{render();home()};filters();render();totals();msg('Добро пожаловать в MIRA HOME. Здесь можно выбрать товары для дома и оформить заказ.');opts([['Открыть каталог'],['Корзина','пока пуста']],x=>x==='Корзина'?openCart():home());
